import Cocoa

/// The completion sound: a short two-note chime generated by tools/make_sound.py.
final class Chime {
    private let sound: NSSound?

    init() {
        let url = Bundle.main.url(forResource: "chime", withExtension: "wav", subdirectory: "Sounds")
            ?? URL(fileURLWithPath: FileManager.default.currentDirectoryPath).appendingPathComponent("Resources/Sounds/chime.wav")
        sound = NSSound(contentsOf: url, byReference: true)
        sound?.volume = 0.7
    }

    func play() {
        sound?.stop()
        sound?.play()
    }
}
